-- ============================================================
-- 180-day Rust challenge tracker (Aug 5, 2026 → Jan 31, 2027) — daily
-- targets seeded from the systems-Rust → ZK → zkML roadmap, tracked from
-- /admin/rust-challenge. Run in Supabase SQL editor: Dashboard → SQL Editor → New Query
-- ============================================================

create table if not exists rust_challenge_days (
  id             uuid primary key default gen_random_uuid(),
  day_number     int not null unique check (day_number between 1 and 180),
  challenge_date date not null unique,
  phase          int not null check (phase between 1 and 4),
  week_number    int not null,
  week_focus     text not null,
  daily_task     text not null,
  dsa_rep        text not null,
  completed      boolean not null default false,
  completed_at   timestamptz,
  x_post_url     text,
  notes          text,
  created_at     timestamptz not null default now()
);

create index if not exists rust_challenge_days_date_idx on rust_challenge_days(challenge_date);

alter table rust_challenge_days enable row level security;

on conflict (day_number) do nothing;
